:root {
  --lime-cream: #ddfcadff;
  --lime-cream-2: #c8e087ff;
  --palm-leaf: #95a472ff;
  --dusty-olive: #82846dff;
  --dim-grey: #646165ff;
  --hotelio-gradient-top: linear-gradient(0deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-right: linear-gradient(90deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-bottom: linear-gradient(180deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-left: linear-gradient(270deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-top-right: linear-gradient(45deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-bottom-right: linear-gradient(135deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-top-left: linear-gradient(225deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-bottom-left: linear-gradient(315deg, #ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-gradient-radial: radial-gradient(#ddfcadff, #c8e087ff, #95a472ff, #82846dff, #646165ff);
  --hotelio-color-bg: var(--lime-cream);
  --hotelio-color-bg-soft: rgba(221, 252, 173, 0.48);
  --hotelio-color-surface: rgba(255, 255, 255, 0.86);
  --hotelio-color-surface-solid: #ffffff;
  --hotelio-color-surface-muted: rgba(200, 224, 135, 0.34);
  --hotelio-color-text: var(--dim-grey);
  --hotelio-color-text-muted: var(--dusty-olive);
  --hotelio-color-primary: var(--dim-grey);
  --hotelio-color-primary-dark: var(--dusty-olive);
  --hotelio-color-primary-soft: var(--lime-cream-2);
  --hotelio-color-danger: var(--dusty-olive);
  --hotelio-color-success: var(--palm-leaf);
  --hotelio-color-warning: var(--lime-cream-2);
  --hotelio-color-border: rgba(130, 132, 109, 0.34);
  --hotelio-color-auth-bg: var(--lime-cream);
  --hotelio-color-auth-panel: rgba(255, 255, 255, 0.88);
  --hotelio-radius-sm: 0.375rem;
  --hotelio-radius-md: 0.5rem;
  --hotelio-radius-lg: 0.75rem;
  --hotelio-form-gap: 1rem;
  --hotelio-grid-height: 34rem;
}

