  justify-content: center;
  padding: clamp(2rem, 5vw, 5rem);
}

.hotelio-login__brand {
  position: relative;
  overflow: hidden;
  background: linear-gradient(155deg, rgba(255, 255, 255, 0.9), rgba(221, 252, 173, 0.72)), radial-gradient(circle at 60% 35%, rgba(149, 164, 114, 0.22), transparent 20rem);
}

