  position: absolute;
  top: 0;
  right: -9rem;
  width: 18rem;
  height: 100%;
  content: "";
  background: rgba(200, 224, 135, 0.48);
  transform: skewX(-12deg);
  transform-origin: top;
}

.hotelio-login__brand-content {
  position: relative;
  z-index: 1;
  width: min(100%, 30rem);
  text-align: center;
}

.hotelio-login__eyebrow {
  margin-bottom: 0.75rem;
  color: var(--hotelio-color-primary);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.hotelio-login__brand h1 {
  margin-bottom: 0.6rem;
  color: var(--hotelio-color-text);
  font-size: clamp(2.6rem, 5vw, 4.25rem);
  font-weight: 800;
  letter-spacing: -0.05em;
}

.hotelio-login__brand h2,
.hotelio-login__header h2 {
  margin-bottom: 0.75rem;
  color: var(--hotelio-color-text);
  font-weight: 750;
  letter-spacing: -0.035em;
}

.hotelio-login__brand p,
.hotelio-login__header p {
  color: var(--hotelio-color-text-muted);
  font-size: 1rem;
  line-height: 1.7;
}

.hotelio-login__illustration {
  position: static;
  display: block;
  width: min(100%, 24rem);
  max-width: 100%;
  height: auto;
  margin: 2rem auto 0;
  transform: none;
  animation: none;
}

.hotelio-login__panel {
  background: radial-gradient(circle at 75% 25%, rgba(221, 252, 173, 0.78), transparent 24rem), rgba(200, 224, 135, 0.62);
}

.hotelio-login__card {
  width: min(100%, 34rem);
  padding: clamp(1.5rem, 4vw, 2.5rem);
  background: rgba(255, 255, 255, 0.78);
  border: 1px solid var(--hotelio-color-border);
  border-radius: 1.25rem;
  box-shadow: 0 1.5rem 4rem rgba(100, 97, 101, 0.16);
  backdrop-filter: blur(16px);
}

.hotelio-login__header {
  margin-bottom: 1.75rem;
  text-align: left;
}

.hotelio-login__header h2 {
  font-size: clamp(1.85rem, 4vw, 2.45rem);
}

.hotelio-field {
  margin-bottom: 1.15rem;
}

.hotelio-field .form-label {
  color: var(--hotelio-color-text) !important;
  font-weight: 700;
}

.hotelio-field .form-control {
  min-height: 3.1rem;
  padding-right: 1rem;
  padding-left: 1rem;
  border-radius: 0.65rem;
  font-size: 1rem;
}

.hotelio-field .form-control::-moz-placeholder {
  color: rgba(130, 132, 109, 0.72);
}

.hotelio-field .form-control:-ms-input-placeholder {
  color: rgba(130, 132, 109, 0.72);
}

.hotelio-field .form-control::placeholder {
  color: rgba(130, 132, 109, 0.72);
}

.hotelio-field .invalid-feedback {
  display: block;
  margin-top: 0.45rem;
  color: var(--dusty-olive);
  font-size: 0.92rem;
}

.hotelio-login__meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.25rem 0 1.25rem;
}

.hotelio-login__meta .form-check {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0;
}

.hotelio-login__meta .form-check-input {
  margin: 0;
}

.hotelio-login__meta .form-check-label,
.hotelio-login__meta a {
  color: var(--hotelio-color-text-muted) !important;
  font-weight: 600;
}

.hotelio-login__meta a {
  color: var(--hotelio-color-primary) !important;
  text-decoration: none;
}

.hotelio-login__submit {
  width: 100%;
  min-height: 3.1rem;
  border-radius: 0.65rem;
  font-size: 1.05rem;
  font-weight: 700;
}

@media (max-width: 991.98px) {
  .hotelio-login {
    grid-template-columns: 1fr;
  }
  .hotelio-login__brand {
    min-height: auto;
    padding-bottom: 1rem;
  }
  .hotelio-login__brand::after {
    display: none;
  }
  .hotelio-login__illustration {
    width: min(100%, 15rem);
    margin-top: 1rem;
  }
  .hotelio-login__panel {
    padding-top: 1rem;
  }
}
@media (max-width: 575.98px) {
  .hotelio-login__brand,
.hotelio-login__panel {
    padding: 1.25rem;
  }
  .hotelio-login__card {
    padding: 1.25rem;
  }
  .hotelio-login__meta {
    align-items: flex-start;
    flex-direction: column;
  }
}
